<?php

namespace Database\Seeders;

/** Seeds `stories` from database/seeders/data/stories.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class StoriesSeeder extends ContentSeederBase
{
    public const TABLE = 'stories';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        $images = ['cover_image' => 'stories'];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('stories') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
